import{_ as a}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as e,o as r,af as o}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const m=JSON.parse('{"title":"阿里云百炼术语表","description":"百炼、千问、灵码不是同一个东西。三种协议、两套套餐、两套 CLI 也不是。","frontmatter":{"title":"阿里云百炼术语表","description":"百炼、千问、灵码不是同一个东西。三种协议、两套套餐、两套 CLI 也不是。","domain":"product","tags":["model-platform"],"role":"glossary"},"headers":[],"relativePath":"zh/products/bailian/bailian-glossary.md","filePath":"zh/products/bailian/bailian-glossary.md","lastUpdated":1787107158000}'),d={name:"zh/products/bailian/bailian-glossary.md"};function l(n,t,i,h,s,p){return r(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="阿里云百炼术语表" tabindex="-1">阿里云百炼术语表 <a class="header-anchor" href="#阿里云百炼术语表" aria-label="Permalink to &quot;阿里云百炼术语表&quot;">​</a></h1><p>不教操作。只把容易撞车的名字拆开。选哪条路见 <a href="./index.html">学习地图</a>。</p><h2 id="百炼-model-studio" tabindex="-1">百炼 / Model Studio <a class="header-anchor" href="#百炼-model-studio" aria-label="Permalink to &quot;百炼 / Model Studio&quot;">​</a></h2><p><strong>是什么</strong>：阿里云的大模型服务与应用开发平台。英文名 Alibaba Cloud Model Studio。提供模型调用、可视化应用、订阅套餐。<a href="https://help.aliyun.com/zh/model-studio/what-is-model-studio" target="_blank" rel="noreferrer">产品简介</a></p><p><strong>不是什么</strong>：不是通义聊天窗口，不是通义灵码 IDE，不是 ECS / OSS。</p><p><strong>为什么单独成页</strong>：前端把 Qwen 接进自己的站点，走的是这个平台的 API 和计费，不是聊天站。</p><h2 id="千问-qwen" tabindex="-1">千问 Qwen <a class="header-anchor" href="#千问-qwen" aria-label="Permalink to &quot;千问 Qwen&quot;">​</a></h2><p><strong>是什么</strong>：阿里的模型系列，也是独立的对话产品。FAQ 原句：百炼是大模型服务平台，提供包括千问系列在内的多种大模型。<a href="https://help.aliyun.com/zh/model-studio/faq-about-alibaba-cloud-model-studio" target="_blank" rel="noreferrer">FAQ</a></p><p><strong>本目录</strong>：只把它当「百炼上可调用的模型」。对话产品正文见 #83。</p><h2 id="灵码-qoder-cn" tabindex="-1">灵码 / Qoder CN <a class="header-anchor" href="#灵码-qoder-cn" aria-label="Permalink to &quot;灵码 / Qoder CN&quot;">​</a></h2><p><strong>是什么</strong>：阿里云智能编码助手 / 独立 IDE。官方现名 <strong>Qoder CN（原 Lingma）</strong>。<a href="https://help.aliyun.com/zh/model-studio/lingma-agent" target="_blank" rel="noreferrer">接入页</a></p><p><strong>和百炼的关系</strong>：可以填百炼的 Token Plan / Coding Plan / 按量 Key。企业版官方写不支持接入百炼。</p><p><strong>本目录</strong>：一行。完整教程见 #84。</p><h2 id="dashscope" tabindex="-1">DashScope <a class="header-anchor" href="#dashscope" aria-label="Permalink to &quot;DashScope&quot;">​</a></h2><p><strong>是什么</strong>：旧的模型接口品牌。环境变量仍叫 <code>DASHSCOPE_API_KEY</code>，美国主机仍出现 <code>dashscope-us.aliyuncs.com</code>，Coding Plan 页仍出现 <code>dashscope.aliyuncs.com</code>。</p><p><strong>不是什么</strong>：不是另一个要单独开通的「DashScope 产品教程」。对本站读者，它是百炼 API 的历史名字。</p><h2 id="业务空间-workspace" tabindex="-1">业务空间 Workspace <a class="header-anchor" href="#业务空间-workspace" aria-label="Permalink to &quot;业务空间 Workspace&quot;">​</a></h2><p><strong>是什么</strong>：隔离项目 / 团队资源和权限的容器。新 MaaS Base URL 里的 <code>{WorkspaceId}</code> 就是它。<a href="https://help.aliyun.com/zh/model-studio/first-api-call-to-qwen" target="_blank" rel="noreferrer">首次调用</a>、<a href="https://help.aliyun.com/zh/model-studio/get-api-key" target="_blank" rel="noreferrer">获取 API Key</a></p><p><strong>权限规则（官方）</strong>：</p><ul><li>同一空间内的 API Key 权限相同，不必按文生文 / 文生图拆 Key。</li><li>默认空间：可调标准模型 + 该空间应用。</li><li>子空间：只能调已授权的标准模型 + 该空间应用。</li><li>调优后的模型：只用它所在空间的 Key。</li></ul><p>主账号能看所有空间的 Key；子账号只能看已加入的空间。</p><h2 id="三种调用协议" tabindex="-1">三种调用协议 <a class="header-anchor" href="#三种调用协议" aria-label="Permalink to &quot;三种调用协议&quot;">​</a></h2><p>同一模型在清单页常同时给出三条主机：</p><table tabindex="0"><thead><tr><th>协议</th><th>路径特征</th><th>什么时候用</th></tr></thead><tbody><tr><td>OpenAI 兼容</td><td><code>/compatible-mode/v1</code></td><td>已有 <code>openai</code> SDK、多数桌面客户端</td></tr><tr><td>Anthropic 兼容</td><td><code>/apps/anthropic</code></td><td>Claude Code 等走 Messages 的工具</td></tr><tr><td>DashScope</td><td><code>/api/v1</code></td><td>官方 DashScope SDK、部分多模态生成</td></tr></tbody></table><p>来源：<a href="https://help.aliyun.com/zh/model-studio/models" target="_blank" rel="noreferrer">选择模型</a>。三条主机<strong>不能</strong>互换；Coding Plan / Token Plan 还有第四套专属主机。</p><h2 id="token-plan-vs-coding-plan" tabindex="-1">Token Plan vs Coding Plan <a class="header-anchor" href="#token-plan-vs-coding-plan" aria-label="Permalink to &quot;Token Plan vs Coding Plan&quot;">​</a></h2><p>都是百炼卖的订阅，<strong>不能互相迁移或升级</strong>。<a href="https://help.aliyun.com/zh/model-studio/token-plan-overview" target="_blank" rel="noreferrer">Token Plan</a></p><table tabindex="0"><thead><tr><th></th><th>Token Plan</th><th>Coding Plan</th></tr></thead><tbody><tr><td>计量</td><td>Credits</td><td>请求次数</td></tr><tr><td>官方态度（2026-08）</td><td>推荐新订，模型与 Harness 更多</td><td>Lite 已停；Pro 限量</td></tr><tr><td>个人 vs 团队</td><td>个人版有 7 天窗口；团队版按座席包月、承诺不训练</td><td>页上以 Pro 为主</td></tr><tr><td>数据</td><td>个人版用于改进；团队版承诺不用</td><td>输入和输出都用于改进</td></tr><tr><td>合法用法</td><td>兼容 OpenAI / Anthropic 的工具</td><td><strong>仅限</strong>编程工具，禁止当后端 API</td></tr></tbody></table><p>FAQ / 国际站简介里「绝不会用你的数据训练」是简化口径。以产品简介「重要」框和两份套餐页为准。</p><h2 id="agent-1-0-vs-2-0" tabindex="-1">Agent 1.0 vs 2.0 <a class="header-anchor" href="#agent-1-0-vs-2-0" aria-label="Permalink to &quot;Agent 1.0 vs 2.0&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>1.0</th><th>2.0</th></tr></thead><tbody><tr><td>调度</td><td>先检索知识库，再决定是否调 MCP</td><td>知识库和 MCP 都是工具，由模型规划顺序</td></tr><tr><td>过程</td><td>只给最终结果</td><td>展示规划-执行-反思</td></tr><tr><td>迁移</td><td>—</td><td><strong>不能</strong>从 1.0 升级，只能新建</td></tr></tbody></table><p>来源：<a href="https://help.aliyun.com/zh/model-studio/new-single-agent-application" target="_blank" rel="noreferrer">新版智能体</a>。无旧依赖时官方推荐 2.0。</p><p>工作流是另一类可视化应用（固定节点图），不是 Agent 2.0 的别名。<a href="https://help.aliyun.com/zh/model-studio/workflow-application/" target="_blank" rel="noreferrer">工作流</a></p><h2 id="知识库-rag" tabindex="-1">知识库 RAG <a class="header-anchor" href="#知识库-rag" aria-label="Permalink to &quot;知识库 RAG&quot;">​</a></h2><p>把私有文档检索后喂给模型。和「直接调模型」是两个计费项：知识库按规格时长 + 调用计费，不吃节省计划 / 资源包。<a href="https://help.aliyun.com/zh/model-studio/what-is-model-studio" target="_blank" rel="noreferrer">产品简介</a></p><p>降低幻觉的官方手段之一，见 FAQ「模型幻觉」。原理见 <a href="/zh/tech/fundamentals/LLM.html">LLM 基础</a>，不要在本页展开注意力。</p><h2 id="mcp" tabindex="-1">MCP <a class="header-anchor" href="#mcp" aria-label="Permalink to &quot;MCP&quot;">​</a></h2><p>模型上下文协议。百炼的智能体 / 工作流可挂官方 MCP 或自定义 MCP。<a href="https://help.aliyun.com/zh/model-studio/mcp-introduction" target="_blank" rel="noreferrer">MCP 简介</a></p><p>部分官方 MCP（文生图、文生视频、语音、联网搜索）会单独计费。自定义 MCP 有基础 / 极速两种时长计费。部署费用是否仍「限时免费」以该页为准。</p><h2 id="百炼-cli-vs-阿里云-cli" tabindex="-1">百炼 CLI vs 阿里云 CLI <a class="header-anchor" href="#百炼-cli-vs-阿里云-cli" aria-label="Permalink to &quot;百炼 CLI vs 阿里云 CLI&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>百炼 CLI</th><th>阿里云 CLI 插件</th></tr></thead><tbody><tr><td>包 / 命令</td><td>npm <code>bailian-cli</code>，命令 <code>bl</code> / <code>bailian</code></td><td><code>aliyun bailian ...</code></td></tr><tr><td>用途</td><td>给本机 Agent 调模型与多模态原子能力</td><td>管类目、文件、连接器等 OpenAPI</td></tr><tr><td>文档</td><td><a href="https://bailian.aliyun.com/cli/install.md" target="_blank" rel="noreferrer">install.md</a></td><td><a href="https://next.api.aliyun.com/api-tools/cli/bailian/2023-12-29" target="_blank" rel="noreferrer">OpenAPI CLI 中心</a></td></tr></tbody></table><p>装错的典型症状：能 <code>aliyun bailian list-file</code>，却没有 <code>bl text chat</code>。</p><h2 id="高代码应用" tabindex="-1">高代码应用 <a class="header-anchor" href="#高代码应用" aria-label="Permalink to &quot;高代码应用&quot;">​</a></h2><p>把 Python 项目部署成带运维和日志的后端服务。官方入口：<a href="https://help.aliyun.com/zh/model-studio/rich-code-application/" target="_blank" rel="noreferrer">高代码应用</a>。轴 B 偏后端平台，本站不写教程。</p>',44)])])}const f=a(d,[["render",l]]);export{m as __pageData,f as default};
